   310      for (list_item *li = list_front(src->subkeys); li; li = list_next(li)) {
   311          pgp_transferable_subkey_t *lskey = (pgp_transferable_subkey_t *) li;
   312          pgp_transferable_subkey_t *subkey = transferable_key_has_subkey(dst, &lskey->subkey);
   313          if (subkey) {
   314              if ((ret = transferable_subkey_merge(subkey, lskey))) {
